package handlers

import (
    "encoding/json"
    "net/http"
)

type greeting struct {
    Message string `json:"message"`
}

// HelloWorldIAmMK handles GET /hello_world_i_am_mk and returns a JSON greeting.
func HelloWorldIAmMK(w http.ResponseWriter, r *http.Request) {
    if r.Method != http.MethodGet {
        http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
        return
    }
    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusOK)
    resp := greeting{Message: "Hello, world! I am MK"}
    json.NewEncoder(w).Encode(resp)
}

package handlers

import (
    "encoding/json"
    "net/http"
    "net/http/httptest"
    "testing"
)

type greeting struct {
    Message string `json:"message"`
}

func TestHelloWorldIAmMK(t *testing.T) {
    req := httptest.NewRequest(http.MethodGet, "/hello_world_i_am_mk", nil)
    rr := httptest.NewRecorder()

    HelloWorldIAmMK(rr, req)

    if status := rr.Code; status != http.StatusOK {
        t.Fatalf("expected status %d, got %d", http.StatusOK, status)
    }

    if ct := rr.Header().Get("Content-Type"); ct != "application/json" {
        t.Fatalf("expected Content-Type application/json, got %s", ct)
    }

    var resp greeting
    if err := json.NewDecoder(rr.Body).Decode(&resp); err != nil {
        t.Fatalf("failed to decode response body: %v", err)
    }

    expected := "Hello, world! I am MK"
    if resp.Message != expected {
        t.Fatalf("expected message %q, got %q", expected, resp.Message)
    }
}

